#include <stdio.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>

int main() {
    // Define a delay of 300,000 microseconds (0.3 seconds)
    useconds_t micro_delay = 300000;

    printf("Starting 5 cycles of 0.3 second delays...\n");

    for (int i = 0; i < 5; i++) {
        long start_sec = time(NULL);
        printf("Cycle %d: Waiting (0.3s)...	", i + 1);
        fflush(stdout);

        // Attempt to suspend execution
        if (usleep(micro_delay) == -1) {
            if (errno == EINTR) {
                // Handle interruption by a signal
                perror("usleep was interrupted");
            } else if (errno == EINVAL) {
                // Handle invalid value (if >= 1,000,000)
                fprintf(stderr, "Error: Invalid microsecond value.\n");
            } else {
                perror("usleep failed unexpectedly");
            }
            return 1;
        }

        long end_sec = time(NULL);
        // Output approximate elapsed time
        printf("Completed. Approx seconds elapsed since cycle start: %ld\n", end_sec - start_sec);
    }

    return 0;
}
